using System;using System.Collections.Generic;using System.Linq;using System.Text.Json;using Exoduser.UnityPort;using Exoduser.UnityPort.Core;
class Program {
 static void ExistingMarkers(Simulation sim,List<NativeMinimapObjective> list){NativeMinimapObjectives.Collect(sim,list);list.RemoveAll(m=>m.Kind.ToString()=="Region");}
 static int checks,failures;static void Check(bool ok,string why){checks++;if(!ok){failures++;Console.WriteLine("FAIL "+why);}else Console.WriteLine("PASS "+why);}static bool Near(double a,double b)=>Math.Abs(a-b)<.0001;
 static Simulation Make(){var s=new Simulation(SourceStarterFixture.CreateKiSlash(),SourceStarterFixture.Seed);s.Stage.Enabled=true;return s;}
 static string State(Simulation s)=>JsonSerializer.Serialize(new{s.Player.X,s.Player.Y,s.Player.Hp,s.Player.Mana,s.Player.Stamina,s.Kills,s.TickCount,s.FieldBossSpawned,s.FieldBossesEnabled,s.Stage.BossUnlocked,s.Stage.BossAlive,s.Stage.InArena,s.Stage.FieldBossDone,holes=s.SpawnHoles?.Holes.Select(h=>new{h.X,h.Y,h.Size,h.Spawned,h.Triggered}).ToArray(),bosses=s.FieldBosses?.Select(b=>b==null?null:new{b.X,b.Y,b.Hp,b.El,b.Alive,b.Asleep,b.T}).ToArray()});
 static int Main(string[] args){var list=new List<NativeMinimapObjective>();list.Add(new NativeMinimapObjective(NativeMinimapObjectiveKind.Hole,0,0,0,0,""));ExistingMarkers(null,list);Check(list.Count==0,"null clears old markers");
 var s=Make();s.EnableFieldSpawns();s.Stage.Enabled=false;ExistingMarkers(s,list);Check(list.Count==0,"disabled practice/flow has no field objectives");s.Stage.Enabled=true;ExistingMarkers(s,list);Check(list.Count==14&&list.All(m=>m.Kind==NativeMinimapObjectiveKind.Hole),"all fourteen remaining Core holes shown");Check(list.Count>0&&Near(list[0].Radius,2.25)&&list[0].Color=="#aa4444"&&Near(list[0].X,2980)&&Near(list[0].Y,6740),"hole position/color/size read from existing state");
 s.SpawnHoles.Holes.RemoveAt(0);ExistingMarkers(s,list);Check(list.Count==13&&list.All(m=>m.X!=2980||m.Y!=6740),"finished hole disappears without stale cached marker");s.SpawnHoles.Holes.Clear();s.Regions=new[]{new RegionState(),new RegionState(),new RegionState(),new RegionState()};ExistingMarkers(s,list);Check(list.Count==0,"disabled field-boss capability does not fabricate targets");
 s.EnableFieldBosses();ExistingMarkers(s,list);var fallback=list.ToArray();Check(fallback.Length==4&&fallback.All(m=>m.Kind==NativeMinimapObjectiveKind.Angler),"four pre-spawn site markers when Core capability enabled");s.TickFieldBosses();ExistingMarkers(s,list);Check(list.Count==4&&s.FieldBosses!=null,"real Core initial field bosses shown");Check(fallback.Length==4&&s.FieldBosses!=null&&fallback.Select((m,i)=>Near(m.X,s.FieldBosses[i].X)&&Near(m.Y,s.FieldBosses[i].Y)&&m.Color==Simulation.ElementColor(s.FieldBosses[i].El)).All(v=>v),"fallback sites/elements agree with actual private Core spawn table");
 s.FieldBosses[0].Hp=0;s.FieldBosses[1]=null;ExistingMarkers(s,list);Check(list.Count==2&&list.All(m=>m.Index>=2),"dead/null anglers removed immediately");s.Stage.FieldBossDone=true;ExistingMarkers(s,list);Check(list.Count==0,"field-boss completion hides stale targets");
 var gate=Make();gate.Regions=new[]{new RegionState(),new RegionState(),new RegionState(),new RegionState()};var tiles=new int[210*210];tiles[5*210+100]=tiles[5*210+101]=3;gate.Stage.InitializeField(tiles,210);ExistingMarkers(gate,list);Check(list.Count==1&&list[0].Kind==NativeMinimapObjectiveKind.Gate&&!list[0].Unlocked&&list[0].Color=="#ff4444"&&Near(list[0].X,4020)&&Near(list[0].Y,220),"locked gate follows authoritative Core gate coordinates");
 gate.Stage.BossUnlocked=true;ExistingMarkers(gate,list);Check(list.Count==1&&list[0].Unlocked&&list[0].Color=="#44aaff","unlocked gate reads real flag without changing it");gate.EnableFieldSpawns();gate.EnableFieldBosses();gate.Stage.InArena=true;ExistingMarkers(gate,list);Check(list.Count==0,"arena never displays stale field objectives");gate.Stage.InArena=false;gate.Stage.BossAlive=false;gate.Stage.FieldBossDone=true;gate.SpawnHoles.Holes.Clear();ExistingMarkers(gate,list);Check(list.Count==0,"defeated boss hides field gate");
 var p=NativeMinimapObjectives.Project(4200,4200,210,210,40);Check(Near(p.X,65)&&Near(p.Y,65),"field projection matches current texture scale and padding");p=NativeMinimapObjectives.Project(2560,2160,128,108,40);Check(Near(p.X,65)&&Near(p.Y,65.5539772727),"non-square arena projection uses active dimensions");
 var read=Make();read.EnableFieldSpawns();read.Regions=new[]{new RegionState(),new RegionState(),new RegionState(),new RegionState()};read.Stage.InitializeField(tiles,210);read.EnableFieldBosses();string before=State(read);for(int i=0;i<5;i++)ExistingMarkers(read,list);Check(State(read)==before&&list.Count==19&&read.FieldBosses==null&&!read.FieldBossSpawned,"nineteen objective views never spawn/tick/move/heal/unlock the simulation");
 var region=Make();region.Regions=new[]{new RegionState{Total=23},new RegionState{Total=23},new RegionState{Total=23},new RegionState{Total=23}};region.RegMidX=region.RegMidY=105;
 NativeMinimapObjectives.Collect(region,list);Check(list.Count(m=>m.Kind.ToString()=="Region")==4,"all four unpurified regions have persistent minimap targets");
 region.Regions[0].Cleared=true;NativeMinimapObjectives.Collect(region,list);Check(list.Count(m=>m.Kind.ToString()=="Region")==3&&list.All(m=>m.Kind.ToString()!="Region"||m.Index!=0),"purified region marker disappears immediately");
 region.Stage.InArena=true;NativeMinimapObjectives.Collect(region,list);Check(list.Count==0,"arena hides region overlays and all field markers");region.Stage.InArena=false;
 region.Player.X=region.Player.Y=40;region.Regions[0]=new RegionState{Id=0,Total=23,Kills=17,FbIdx=2};region.RegGateIdx=0;
 var goal=NativeHellGateObjective.Read(region);Check(goal.Visible&&goal.Required==19&&goal.Kills==17&&goal.AnglerAlive&&!goal.RegionCleared,"17/23 reports the actual 17/19 target plus the pre-spawn living angler");
 region.Stage.GateGuardKilled=true;goal=NativeHellGateObjective.Read(region);Check(goal.Required==17,"Core gate-guard bonus lowers 23-enemy target to 17");region.RegGateIdx=1;Check(NativeHellGateObjective.Read(region).Required==19,"guard bonus never leaks into a different region");
 region.RegGateIdx=0;region.Regions[0].Total=100;region.Regions[0].Kills=70;Check(NativeHellGateObjective.Read(region).Required==70,"exact 70/100 bonus boundary does not round up to 71");
 bool thresholds=true;for(int total=1;total<=200;total++)foreach(bool bonus in new[]{false,true}){region.Regions[0].Total=total;region.Stage.GateGuardKilled=bonus;int expected=0;while(expected<=total){region.Regions[0].Kills=expected;if(region.RegionRatio(region.Regions[0],0)>=Simulation.RegionClearRatio-1e-9)break;expected++;}if(NativeHellGateObjective.Read(region).Required!=expected)thresholds=false;}Check(thresholds,"400 displayed thresholds agree with actual Core ratio comparison");
 region.Regions[0].Kills=17;region.Regions[0].Total=23;region.Stage.GateGuardKilled=false;region.EnableFieldBosses();region.TickFieldBosses();region.FieldBosses[2].Hp=0;goal=NativeHellGateObjective.Read(region);Check(!goal.AnglerAlive&&goal.Required==19&&!goal.RegionCleared,"slain angler alone never claims a region is purified");
 region.Regions[0].Kills=19;region.RegionCheckClears();goal=NativeHellGateObjective.Read(region);Check(goal.RegionCleared&&goal.Cleared==1,"real Core purification immediately changes objective state");
 foreach(var r in region.Regions)r.Cleared=true;region.Stage.BossUnlocked=true;Check(NativeHellGateObjective.Read(region).GateOpen&&NativeHellGateObjective.Read(region).Cleared==4,"four-of-four open gate exposes boss-room direction state");
 region.Stage.InArena=true;Check(!NativeHellGateObjective.Read(region).Visible,"arena removes field tracker");region.Stage.InArena=false;
 string original=State(region);for(int i=0;i<8;i++)NativeHellGateObjective.Read(region);Check(original==State(region),"objective reads do not tick, heal, spawn or unlock Core");
 region.Regions[0].Total=0;region.Regions[0].Kills=0;Check(NativeHellGateObjective.Read(region).Required==0,"empty region does not divide by zero");Check(!NativeHellGateObjective.Read(null).Visible,"null simulation has no tracker");
 var report=new{scope="Read-only UI model with actual Core; explicit unit fixtures, not Unity Player/render/natural play",checks,failures};System.IO.File.WriteAllText(args[0],JsonSerializer.Serialize(report));Console.WriteLine(JsonSerializer.Serialize(report));return failures==0?0:1;}
}
